//! Golden-vector conformance for the noise layer (ORACLE.md §5, G1).
//!
//! Replays `ImprovedNoise` / `PerlinNoise` / `NormalNoise` samples taken
//! from real vanilla 26.2 (`golden/noise_vectors.json`, generated by
//! `tools/goldengen`). Everything is compared as raw IEEE-754 bits: a noise
//! value that is merely *close* is a failure, because the density functions
//! above this layer amplify the difference into different blocks.

use rustmc_worldgen::noise::{BlendedNoise, ImprovedNoise, NormalNoise, PerlinNoise, SimplexNoise};
use rustmc_worldgen::rng::XoroshiroRandomSource;
use serde_json::Value;

const GOLDEN: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/golden/noise_vectors.json");

fn load() -> Value {
    let text = std::fs::read_to_string(GOLDEN)
        .unwrap_or_else(|e| panic!("golden vector {GOLDEN} unreadable: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{GOLDEN} is not JSON: {e}"))
}

/// Bit patterns travel as strings; a JSON number cannot hold an i64.
fn bits(v: &Value) -> u64 {
    v.as_str()
        .unwrap_or_else(|| panic!("expected bits-as-string, got {v}"))
        .parse::<i64>()
        .unwrap_or_else(|e| panic!("bad i64 {v}: {e}")) as u64
}

fn double(v: &Value) -> f64 {
    f64::from_bits(bits(v))
}

fn doubles(v: &Value) -> Vec<f64> {
    v.as_array().expect("array").iter().map(double).collect()
}

fn points(case: &Value) -> Vec<(f64, f64, f64)> {
    case["points"]
        .as_array()
        .expect("points")
        .iter()
        .map(|p| {
            let p = p.as_array().expect("[x,y,z]");
            (double(&p[0]), double(&p[1]), double(&p[2]))
        })
        .collect()
}

fn seed(case: &Value) -> i64 {
    case["seed"].as_str().expect("seed").parse().expect("i64")
}

#[track_caller]
fn assert_samples(label: &str, case: &Value, mut sample: impl FnMut(f64, f64, f64) -> f64) {
    let expected = case["output_bits"].as_array().expect("output_bits");
    for (index, (point, want)) in points(case).iter().zip(expected).enumerate() {
        let (x, y, z) = *point;
        let got = sample(x, y, z);
        let want_bits = bits(want);
        assert_eq!(
            got.to_bits(),
            want_bits,
            "{label}: diverged at point {index} ({x}, {y}, {z})\n  \
             expected {} (0x{want_bits:016x})\n  got      {got} (0x{:016x})",
            f64::from_bits(want_bits),
            got.to_bits()
        );
    }
}

#[test]
fn noise_vectors_match_vanilla() {
    let doc = load();
    let cases = doc["cases"].as_array().expect("cases");
    let mut seen = 0usize;

    for case in cases {
        let name = case["case"].as_str().expect("case name");
        seen += 1;

        match name {
            "ImprovedNoise.noise" => {
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = ImprovedNoise::new(&mut rng);

                // Offsets first: if these are wrong every sample is wrong,
                // and the failure is far easier to read here.
                assert_eq!(
                    noise.xo.to_bits(),
                    bits(&case["xo_bits"]),
                    "ImprovedNoise xo (seed {})",
                    seed(case)
                );
                assert_eq!(
                    noise.yo.to_bits(),
                    bits(&case["yo_bits"]),
                    "ImprovedNoise yo"
                );
                assert_eq!(
                    noise.zo.to_bits(),
                    bits(&case["zo_bits"]),
                    "ImprovedNoise zo"
                );

                assert_samples(
                    &format!("ImprovedNoise.noise (seed {})", seed(case)),
                    case,
                    |x, y, z| noise.noise(x, y, z),
                );
            }
            "ImprovedNoise.noiseWithFudge" => {
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = ImprovedNoise::new(&mut rng);
                let y_scale = double(&case["yScale_bits"]);
                let y_fudge = double(&case["yFudge_bits"]);
                assert_samples(
                    &format!("ImprovedNoise.noiseWithFudge({y_scale}, {y_fudge})"),
                    case,
                    |x, y, z| noise.noise_with_fudge(x, y, z, y_scale, y_fudge),
                );
            }
            "PerlinNoise.getValue" => {
                let first_octave = case["firstOctave"].as_i64().expect("firstOctave") as i32;
                let amplitudes = doubles(&case["amplitudes"]);
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = PerlinNoise::create(&mut rng, first_octave, &amplitudes);
                assert_samples(
                    &format!("PerlinNoise.getValue(firstOctave {first_octave}, {amplitudes:?})"),
                    case,
                    |x, y, z| noise.get_value(x, y, z),
                );
            }
            "NormalNoise.getValue" => {
                let first_octave = case["firstOctave"].as_i64().expect("firstOctave") as i32;
                let amplitudes = doubles(&case["amplitudes"]);
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = NormalNoise::create(&mut rng, first_octave, &amplitudes);

                assert_eq!(
                    noise.max_value().to_bits(),
                    bits(&case["maxValue_bits"]),
                    "NormalNoise maxValue (firstOctave {first_octave}, {amplitudes:?})"
                );
                assert_samples(
                    &format!("NormalNoise.getValue(firstOctave {first_octave}, {amplitudes:?})"),
                    case,
                    |x, y, z| noise.get_value(x, y, z),
                );
            }
            "BlendedNoise.compute" => {
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = BlendedNoise::new(
                    &mut rng,
                    double(&case["xzScale_bits"]),
                    double(&case["yScale_bits"]),
                    double(&case["xzFactor_bits"]),
                    double(&case["yFactor_bits"]),
                    double(&case["smear_bits"]),
                );

                assert_eq!(
                    noise.max_value().to_bits(),
                    bits(&case["maxValue_bits"]),
                    "BlendedNoise maxValue"
                );

                // Block coordinates here, not the shared f64 sample points.
                let expected = case["output_bits"].as_array().expect("output_bits");
                let block_points = case["blockPoints"].as_array().expect("blockPoints");
                for (index, (point, want)) in block_points.iter().zip(expected).enumerate() {
                    let p = point.as_array().expect("[x,y,z]");
                    let (x, y, z) = (
                        p[0].as_i64().expect("x") as i32,
                        p[1].as_i64().expect("y") as i32,
                        p[2].as_i64().expect("z") as i32,
                    );
                    let got = noise.compute(x, y, z);
                    let want_bits = bits(want);
                    assert_eq!(
                        got.to_bits(),
                        want_bits,
                        "BlendedNoise.compute: diverged at point {index} ({x}, {y}, {z})\n  \
                         expected {} (0x{want_bits:016x})\n  got      {got} (0x{:016x})",
                        f64::from_bits(want_bits),
                        got.to_bits()
                    );
                }
            }
            "SimplexNoise.2d" | "SimplexNoise.3d" => {
                let mut rng = XoroshiroRandomSource::from_seed(seed(case));
                let noise = SimplexNoise::new(&mut rng);
                let three_d = name.ends_with("3d");
                assert_samples(&format!("{name} (seed {})", seed(case)), case, |x, y, z| {
                    if three_d {
                        noise.get_value_3d(x, y, z)
                    } else {
                        // The 2D form takes (x, z).
                        noise.get_value_2d(x, z)
                    }
                });
            }
            other => panic!("unhandled noise case {other:?} — a skipped case proves nothing"),
        }
    }

    assert_eq!(seen, cases.len());
    assert!(seen >= 22, "expected the full noise case set, saw {seen}");
}
